/**
 * Snapshot the Python evaluator into a TypeScript module the app can import.
 *
 * Staging's server build ignores custom rsbuild loaders and cannot resolve
 * files outside the app folder. Importing `.py` as `asset/source` or reaching
 * into `Projects/hackathon-usage-verifier` would pack a broken remote.
 *
 * Source of truth for the algorithm remains the Python files. Re-run this
 * script after editing them. Do not edit the generated module by hand.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const appRoot = path.resolve(here, '..');
const workspaceRoot = path.resolve(appRoot, '..', '..');
const evalRoot = path.join(workspaceRoot, 'Projects', 'hackathon-usage-verifier', 'eval');
const verifyRoot = path.join(appRoot, 'src', 'verify');
const outFile = path.join(verifyRoot, 'generated', 'evaluatorBundle.ts');

const FILES = [
	['hj/engine.py', path.join(evalRoot, 'engine.py')],
	['hj/target.py', path.join(evalRoot, 'target.py')],
	['hj/targets/rocketride.json', path.join(evalRoot, 'targets', 'rocketride.json')],
	['hj/sandbox_github.py', path.join(verifyRoot, 'sandboxGithub.py')],
	['hj/run_batch.py', path.join(verifyRoot, 'run_batch.py')],
	['hj/run_verify.py', path.join(verifyRoot, 'run_verify.py')],
	['hj/extract.py', path.join(evalRoot, 'extract.py')],
	['hj/run_extract.py', path.join(verifyRoot, 'run_extract.py')],
];

const bundle = FILES.map(([dest, abs]) => {
	if (!fs.existsSync(abs)) {
		throw new Error(`Evaluator source missing: ${abs}`);
	}
	return [dest, fs.readFileSync(abs, 'utf8')];
});

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(
	outFile,
	[
		'/* Generated by tools/gen-evaluator-bundle.mjs — do not edit. */',
		'export const EVALUATOR_BUNDLE: Array<[string, string]> = ',
		`${JSON.stringify(bundle, null, '\t')};`,
		'',
	].join('\n'),
	'utf8',
);

const bytes = fs.statSync(outFile).size;
console.log(`Wrote ${outFile} (${bundle.length} files, ${bytes} bytes)`);
